/**
 * Prompt suggestions (Phase 7): the logical next user message after a settled turn, either
 * native to the provider or generated by bigbud. Ingestion projects the latest one onto the
 * thread as a `prompt.suggestion` activity bound to its turn. Schema only.
 *
 * @module orchestration.promptSuggestion
 */
import { Schema } from "effect";

import { TrimmedNonEmptyString } from "../core/baseSchemas";
import { ProviderKind } from "./orchestration.provider";

export const PROMPT_SUGGESTION_ACTIVITY_KIND = "prompt.suggestion";

/** Bounds after normalization; anything outside is dropped, never truncated. */
export const PROMPT_SUGGESTION_MIN_LENGTH = 15;
export const PROMPT_SUGGESTION_MAX_LENGTH = 150;
/** Upper bound for a raw provider suggestion before normalization. */
export const PROMPT_SUGGESTION_RAW_MAX_LENGTH = 4_000;

export const PromptSuggestionSource = Schema.Literals(["native", "generated"]);
export type PromptSuggestionSource = typeof PromptSuggestionSource.Type;

/** Runtime payload of `turn.prompt-suggestion`; thread, turn and provider are on the envelope. */
export const TurnPromptSuggestionPayload = Schema.Struct({
  suggestion: Schema.String.check(Schema.isMaxLength(PROMPT_SUGGESTION_RAW_MAX_LENGTH)),
  source: PromptSuggestionSource,
});
export type TurnPromptSuggestionPayload = typeof TurnPromptSuggestionPayload.Type;

/** Payload of the `prompt.suggestion` activity (already normalized). */
export const PromptSuggestionActivityPayload = Schema.Struct({
  suggestion: TrimmedNonEmptyString.check(Schema.isMaxLength(PROMPT_SUGGESTION_MAX_LENGTH)),
  source: PromptSuggestionSource,
  provider: ProviderKind,
});
export type PromptSuggestionActivityPayload = typeof PromptSuggestionActivityPayload.Type;
